/bin/bash -lc "node --input-type=module <<'JS'
import fs from 'node:fs';
const path = 'src/data.ts';
let code = fs.readFileSync(path, 'utf8');
code = code.replace('const length = minutes * 60;', 'const length = minutes * 60;\\n  const sampleEnd = Math.floor(end / 1000);\\n  const signal = (index: number) => sampleEnd - length + 1 + index;');
code = code.replaceAll('Math.sin(i / 43)', 'Math.sin(signal(i) / 43)').replaceAll('Math.sin(i * 1.76)', 'Math.sin(signal(i) * 1.76)').replaceAll('i % 487 < 12', 'signal(i) % 487 < 12').replaceAll('Math.sin(i / 77)', 'Math.sin(signal(i) / 77)').replaceAll('Math.cos(i * 1.24)', 'Math.cos(signal(i) * 1.24)');
fs.writeFileSync(path, code);
const appPath = 'src/App.tsx';
code = fs.readFileSync(appPath, 'utf8').replace(\"  const count = Math.round(total / 3240);\", \"  const count = Math.round(total / 3240);\\n  const previousCount = Math.round(previous / (3240 / 1.052));\\n  const ordersGrowth = ((count / previousCount - 1) * 100).toFixed(1).replace('.', ',');\");
code = code.replace(\"change={sales ? "'`+${growth}%` : '"'+0,02%'}\", \"change={sales ? "'`+${ordersGrowth}%` : '"'+0,02%'}\");
code = code.replace('Для интеграции передайте собственные временные ряды в API VisualizationWidget.', 'Переключайтесь между источниками с помощью вкладок «Продажи» и «Мониторинг».');
code = code.replace('Сравнение периодов</span>', 'Сравнение периодов</span>');
fs.writeFileSync(appPath, code);
fs.writeFileSync('index.html', fs.readFileSync('index.html', 'utf8').replace('Gravity UI eval', 'Pulse — Визуализация данных'));
fs.writeFileSync('vite.config.ts', fs.readFileSync('vite.config.ts', 'utf8').replace('plugins: [react()],', 'plugins: [react()],\\n  build: {manifest: true},'));
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8')); pkg.scripts.test = 'vitest run'; fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\\n');
JS
cat > src/data.test.ts <<'EOF'
import {describe, expect, it} from 'vitest';
import {END_DATE, getMonitoringData, getSalesData} from './data';

describe('widget data contract', () => {
  it.each([7, 30, 90])('provides %i daily sales points and aligned comparison dates', days => {
    const [current, previous] = getSalesData(days);
    expect(current.data).toHaveLength(days);
    expect(current.data.at(-1)?.x).toBe(END_DATE);
    expect(current.data.map(p => p.x)).toEqual(previous.data.map(p => p.x));
    expect(current.data.every((p, i) => p.y >= 0 && (i === 0 || p.x - current.data[i - 1].x === 86400000))).toBe(true);
  });
  it('provides a dense, aligned, one-second monitoring timeline', () => {
    const end = 1_790_000_000_000;
    const series = getMonitoringData(60, end);
    for (const s of series) {
      expect(s.data).toHaveLength(3600);
      expect(s.data.at(-1)?.x).toBe(end);
      expect(s.data.every((p, i) => Number.isFinite(p.y) && (i === 0 || p.x - s.data[i - 1].x === 1000))).toBe(true);
    }
    expect(series[0].data.map(p => p.x)).toEqual(series[1].data.map(p => p.x));
  });
  it('retains historical values when a live window advances', () => {
    const before = getMonitoringData(15, 1_790_000_000_000);
    const after = getMonitoringData(15, 1_790_000_005_000);
    for (let index = 0; index < before.length; index++) {
      expect(before[index].data.slice(5)).toEqual(after[index].data.slice(0, -5));
    }
  });
});
EOF
cat > README.md <<'EOF'
# Pulse

Один виджет Gravity UI для линейного графика продаж и плотного ряда мониторинга.

"'```tsx
import {VisualizationWidget} from '"'./src/VisualizationWidget';

<VisualizationWidget
  mode=\"sales\" // либо \"monitoring\"
  series={[{
    id: 'revenue',
    name: 'Выручка',
    color: 'var(--g-color-text-brand)',
    data: [{x: 1790000000000, y: 120}, {x: 1790086400000, y: 145}],
  }]}
  height={310}
/>
"'```

Оба режима используют `VisualizationWidgetProps`: `mode`, `series`, `height`,
`loading`, `error`, `onRetry`. Время `x` всегда задаётся в Unix milliseconds.
Компонент самостоятельно адаптирует единый формат к Gravity Charts и Yagr;
импортировать движки вызывающему коду не нужно. Приложение должно быть обёрнуто
в UIKit `ThemeProvider` и подключать стили UIKit, как в `src/main.tsx`.

`src/chartRegistry.ts` регистрирует ленивые плагины ChartKit через `React.lazy`
и `import()`. Даже точка входа gravity-charts загружается динамически, поскольку
она реэкспортирует движок. Код и CSS Yagr загружаются при первом открытии
мониторинга. Повторные переключения используют загруженные модули.

Интерфейс демонстрирует выбор периода, сравнение продаж, скрытие серий,
автообновление мониторинга каждые 5 секунд, настройки высоты и экспорт видимых
серий в CSV. Данные демонстрационные, генерируются локально. Обновление плотного
ряда сохраняет значения для пересекающихся временных отметок. После скрытия всех
серий отображается пустое состояние. Предусмотрены загрузка и ошибки ChartKit.

Команды: `npm run dev`, `npm run build` (typecheck + production build), `npm test`.

Автоматические проверки не оценивают внешний вид. Для визуальной приёмки:
светлая/тёмная тема, ширина 375/1400 px, переключение обоих режимов, пустое
состояние при скрытии серий, состояние загрузки при ограничении сети и ошибка
загрузки чанка.
EOF
npm exec --yes --package=prettier -- prettier --write src/App.tsx src/VisualizationWidget.tsx src/chartRegistry.ts src/data.ts src/data.test.ts src/styles.css vite.config.ts'

