settings.set({
  lang: "ru",
  plugins: [
    {
      type: "gravity-charts",
      renderer: lazy(async () => {
        const { GravityChartsPlugin } =
          await import("@gravity-ui/chartkit/gravity-charts");
        return { default: GravityChartsPlugin.renderer };
      }),
    },
    {
      type: "yagr",
