        <div className=\"section-heading\"><div className=\"section-title\"><span className=\"section-icon\"><Icon data={ChartColumn} size={18}/></span><Text variant=\"subheader-2\">Обзор показателей</Text><span className=\"small-tag\">1 виджет</span></div><div className=\"updated\"><span className=\"status-dot\"/>{refreshed ? 'Только что обновлено' : 'Данные актуальны'}<Button view=\"flat\" size=\"s\" aria-label=\"Обновить данные\" onClick={refresh}><Icon data={ArrowRotateRight} size={15}/></Button></div></div>
        <section className=\"chart-card\" id=\"chart-card\">
          <div className=\"widget-toolbar\"><SegmentedRadioGroup value={mode} onUpdate={changeMode} size=\"l\" className=\"mode-control\" aria-label=\"Режим визуализации\"><SegmentedRadioGroup.Option value=\"sales\"><span className=\"mode-option\"><Icon data={ChartLine} size={17}/>Продажи</span></SegmentedRadioGroup.Option><SegmentedRadioGroup.Option value=\"monitoring\"><span className=\"mode-option\"><Icon data={Pulse} size={17}/>Мониторинг</span></SegmentedRadioGroup.Option></SegmentedRadioGroup><div className=\"widget-tools\"><span className=\"demo-label\">Демо-данные</span><Button view=\"flat\" size=\"m\" aria-label=\"Настроить виджет\" onClick={() => setModal('widget')}><Icon data={Sliders} size={17}/></Button><DropdownMenu size=\"m\" defaultSwitcherProps={{view: 'flat', 'aria-label': 'Действия с виджетом'}} items={[{text: 'Экспортировать CSV', action: download}, {text: 'Обновить данные', action: refresh}, {text: 'Настроить виджет', action: () => setModal('widget')}]}/></div></div>
          <div className=\"widget-heading\"><div><div className=\"widget-title-row\"><Text variant=\"header-1\" as=\"h2\">{sales ? 'Динамика продаж' : 'Мониторинг сервисов'}</Text>{"'!sales && <span className="live-tag"><span className="status-dot"/>{live ? '"'LIVE' : 'ПАУЗА'}</span>}</div><p>{sales ? 'Выручка и ключевые показатели вашего бизнеса' : 'Время ответа сервисов с детализацией до секунды'}</p></div><div className=\"period-picker\"><Icon data={Calendar} size={16}/><Select size=\"m\" value={[sales ? period : minutes]} onUpdate={v => sales ? setPeriod(v[0]) : setMinutes(v[0])} options={sales ? [{value: '7', content: 'Последние 7 дней'}, {value: '30', content: 'Последние 30 дней'}, {value: '90', content: 'Последние 90 дней'}] : [{value: '15', content: 'Последние 15 минут'}, {value: '60', content: 'Последний час'}, {value: '180', content: 'Последние 3 часа'}]} aria-label=\"Период графика\"/></div></div>
          <div className=\"metrics\"><Metric title={sales ? 'Общая выручка' : 'Среднее время ответа'} value={sales ? "'`${fmt(total)} ₽` : `${fmt(allSeries[0].data.reduce((s, p) => s + p.y, 0) / allSeries[0].data.length)} мс`} change={sales ? `+${growth}%` : '"'−12,4%'} note={sales ? 'к предыдущему периоду' : 'за последний час'} primary/><Metric title={sales ? 'Количество заказов' : 'Доступность сервисов'} value={sales ? fmt(count) : '99,98%'} change={sales ? "'`+${growth}%` : '"'+0,02%'} note={sales ? 'к предыдущему периоду' : 'за последние 24 часа'}/><Metric title={sales ? 'Средний чек' : 'Активных сервисов'} value={sales ? "'`${fmt(total / count)} ₽` : '"'2 из 2'} change={sales ? '+5,2%' : 'В норме'} note={sales ? 'к предыдущему периоду' : 'ошибок не обнаружено'}/></div>
          <div className=\"chart-caption\"><span>{sales ? 'Выручка, тыс. ₽' : 'Время ответа, мс'}</span><span>{rangeLabel}</span></div>
          <div className=\"chart-wrapper\"><VisualizationWidget mode={mode} series={visibleSeries} height={Number(chartHeight)}/></div>
          <div className=\"chart-legend\"><div className=\"series-controls\">{allSeries.filter(s => "'!sales || compare || s.id !== '"'previous').map(s => <Button key={s.id} view=\"flat\" size=\"s\" onClick={() => setHidden(h => h.includes(s.id) ? h.filter(id => id "'!== s.id) : [...h, s.id])} className={hidden.includes(s.id) ? '"'legend-button is-hidden' : 'legend-button'} aria-pressed={"'!hidden.includes(s.id)}><span className={`legend-line ${s.dashed ? '"'is-dashed' : ''}"'`} style={{color: s.color}}/>{s.name}</Button>)}</div>{sales ? <Checkbox checked={compare} onUpdate={setCompare} size="m">Сравнить с предыдущим периодом</Checkbox> : <Switch checked={live} onUpdate={setLive} size="m">Обновлять каждые 5 сек.</Switch>}</div>
          <div className="widget-footer"><span><Icon data={Database} size={13}/>{sales ? '"'Sales Analytics' : 'Infrastructure Metrics'}<span className=\"footer-divider\">·</span>{fmt(allSeries[0].data.length)} {sales ? 'точек данных' : 'точек на серию'}</span><span><span className=\"status-dot\"/>Обновлено {new Date(now).toLocaleTimeString('ru-RU', {hour: '2-digit', minute: '2-digit'})}</span></div>
